namespace batch_insert_products {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string name;
  float price;
  std::string category;
  int stock;
};

/**
 * Function: Perform efficient batch insertion of product data using a transaction.
 * 
 * @param products List of products to insert
 * @return true if all inserts succeed, false otherwise
 */
bool batch_insert_products(const std::vector<Product>& products) {
    try {
        // Connect to SQLite database
        auto conn = sqlgen::sqlite::connect("test_db.sqlite");
        if (!conn) {
            return false;
        }

        // Drop the table if it exists
        auto drop_result = conn | sqlgen::drop<Product> | sqlgen::if_exists;
        if (!drop_result) {
            return false;
        }

        // Create the Product table
        auto create_result = conn | sqlgen::create_table<Product>;
        if (!create_result) {
            return false;
        }

        // Begin transaction
        auto transaction_result = conn | sqlgen::begin_transaction;
        if (!transaction_result) {
            return false;
        }

        auto transaction = std::move(transaction_result.value());

        // Insert products using write function
        auto write_result = transaction | sqlgen::write(products);
        if (!write_result) {
            return false;
        }

        // Commit transaction
        auto commit_result = transaction | sqlgen::commit;
        if (!commit_result) {
            return false;
        }

        return true;
    } catch (...) {
        return false;
    }
}

}  // namespace batch_insert_products
