  friend auto operator==(const Operation& _o, const T& _t) {
    return make_condition(conditions::equal(_o, to_transpilation_type(_t)));
  }

  template <class T>
  friend auto operator!=(const Operation& _o, const T& _t) {
    return make_condition(conditions::not_equal(_o, to_transpilation_type(_t)));
