```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace delete_inactive_users {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
  std::optional<sqlgen::DateTime> last_login;
  std::string status = "active";
};

int delete_inactive_users() {
  // Connect to the SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");
  if (conn_result.error()) {
    return -1; // Return error code if connection fails
  }

  auto conn = conn_result.value();

  // Begin transaction
  auto transaction_result = sqlgen::begin_transaction(conn);
  if (transaction_result.error()) {
    return -1; // Return error code if transaction fails to start
  }

  auto transaction = transaction_result.value();

  // Create the date for comparison (2025-01-01)
  const auto cutoff_date = sqlgen::DateTime(2025, 1, 1, 0, 0, 0);

  // Delete inactive users using the transaction
  auto delete_result = sqlgen::delete_from<User> | 
    sqlgen::where(sqlgen::col<"last_login"> < cutoff_date);

  auto exec_result = delete_result(transaction);
  if (exec_result.error()) {
    return -1; // Return error code if deletion fails
  }

  // Commit the transaction
  auto commit_result = sqlgen::commit(transaction);
  if (commit_result.error()) {
    return -1; // Return error code if commit fails
  }

  // Return success code
  return 0;
}

} // namespace delete_inactive_users
