 * Function: Calculate daily traffic metrics from a log table.
 * 
 * @return List of daily traffic metrics
 */
std::vector<DailyTraffic> query_daily_traffic_metrics() {
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn) {
    return {};
  }

  // Create the query using sqlgen DSL
  auto result = sqlgen::select_from<PageVisit>(
      sqlgen::as<"visit_date">(sqlgen::strftime("%Y-%m-%d", PageVisit::visit_time)),
      sqlgen::count(),
      sqlgen::count_distinct(PageVisit::url)
  )
  | sqlgen::group_by(sqlgen::as<"visit_date">(sqlgen::strftime("%Y-%m-%d", PageVisit::visit_time)))
  | sqlgen::order_by(sqlgen::as<"visit_date">(sqlgen::strftime("%Y-%m-%d", PageVisit::visit_time)))
  | sqlgen::to<std::vector<DailyTraffic>>
  | *conn;

  if (!result) {
    return {};
  }

  return std::move(*result);
}

}  // namespace query_daily_traffic_metrics
