#ifndef SQLGEN_SELECT_FROM_HPP_
#define SQLGEN_SELECT_FROM_HPP_

#include <ranges>
#include <rfl.hpp>
#include <rfl/NamedTuple.hpp>
#include <rfl/internal/has_fields.hpp>
