  }

  /// Returns a NOT IN condition.
  template <class... Ts>
  auto not_in(const Ts&... _ts) const noexcept {
    return transpilation::make_condition(transpilation::conditions::not_in(
        transpilation::Col<_name, _alias>{}, _ts...));
  }

