#pragma once

#include <optional>
#include <rfl.hpp>
#include <rfl/json.hpp>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>
#include <vector>

namespace query_search_books_by_criteria {

struct Book {
  sqlgen::PrimaryKey<int> book_id;
  std::string title;
  std::string author;
  int year;
  std::string genre;
  double price;
};

struct BookFilters {
  std::optional<std::string> title_keyword;
  std::optional<int> min_year;
  std::optional<std::string> genre;
  std::optional<double> max_price;
};

/**
 * Function: Search for books based on multiple optional criteria.
 * 
 * @param filters Optional filters for title, year, genre, and price
 * @return List of books matching the criteria
 */
std::vector<Book> query_search_books_by_criteria(const BookFilters& filters) {
    // Connect to the SQLite database
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // Start building the query
    auto query = sqlgen::select_from<Book>(sqlgen::col<"book_id">, 
                                           sqlgen::col<"title">, 
                                           sqlgen::col<"author">, 
                                           sqlgen::col<"year">, 
                                           sqlgen::col<"genre">, 
                                           sqlgen::col<"price">);

    // Build conditions dynamically
    using namespace sqlgen::transpilation::conditions;

    std::optional<decltype(sqlgen::col<"title">.like(""))> title_condition;
    std::optional<decltype(sqlgen::col<"year"> >= 0)> year_condition;
    std::optional<decltype(sqlgen::col<"genre"> == "")> genre_condition;
    std::optional<decltype(sqlgen::col<"price"> <= 0.0)> price_condition;

    // Add title condition if provided
    if (filters.title_keyword.has_value()) {
        title_condition = sqlgen::col<"title">.like("%" + filters.title_keyword.value() + "%");
    }

    // Add min year condition if provided
    if (filters.min_year.has_value()) {
        year_condition = sqlgen::col<"year"> >= filters.min_year.value();
    }

    // Add genre condition if provided
    if (filters.genre.has_value()) {
        genre_condition = sqlgen::col<"genre"> == filters.genre.value();
    }

    // Add max price condition if provided
    if (filters.max_price.has_value()) {
        price_condition = sqlgen::col<"price"> <= filters.max_price.value();
    }

    // Combine conditions
    auto final_condition = sqlgen::make_condition(sqlgen::transpilation::conditions::equal(
        sqlgen::transpilation::Col<"book_id", "">{}, 
        sqlgen::transpilation::Col<"book_id", "">{}));

    bool has_condition = false;

    if (title_condition) {
        if (!has_condition) {
            final_condition = *title_condition;
            has_condition = true;
        } else {
            final_condition = final_condition && *title_condition;
