    auto conn = sqlgen::sqlite::connect("test_db.sqlite");
    if (!conn) {
        return false;
    }

    // Create the sets for the update: is_deleted = 1, deleted_at = CURRENT_TIMESTAMP
    auto is_deleted_col = sqlgen::col<"is_deleted">;
    auto deleted_at_col = sqlgen::col<"deleted_at">;

    auto sets = rfl::Tuple(
        is_deleted_col.set(1),
        deleted_at_col.set(sqlgen::current_timestamp())
    );

    // Create the WHERE condition using IN clause
    auto doc_id_col = sqlgen::col<"doc_id">;
    auto where_condition = sqlgen::where(doc_id_col.in(ids));

    // Perform the update
    auto result = conn | sqlgen::update<Document>(sets) | where_condition;

    return static_cast<bool>(result);
}

