namespace transaction_transfer_funds {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
};

bool transfer_funds(int from_account_id, int to_account_id, double amount) {
  using namespace sqlgen;
  using namespace sqlgen::sqlite;

  auto conn_result = connect("test_db.sqlite");
  if (!conn_result) {
    return false;
  }

  auto conn = conn_result.value();

  // Begin transaction
  auto txn_result = begin_transaction(conn);
  if (!txn_result) {
    return false;
  }

  auto txn = txn_result.value();

  // Check if sender has sufficient funds and deduct amount
  auto deduct_result = update<Account>(
      col<"balance">.set(col<"balance"> - amount)
  ) | where(col<"account_id"> == from_account_id && col<"balance"> >= amount)
  )(txn);

  if (!deduct_result) {
    return false;
  }

  // Check if the update actually affected a row (sufficient funds check)
  // We need to verify that exactly one row was updated
  // Since sqlgen doesn't directly expose row count, we'll do a select first
  auto sender_check = select(col<"account_id">, col<"balance">)
                     .from<Account>()
                     .where(col<"account_id"> == from_account_id && 
                            col<"balance"> >= amount)(txn);

  if (!sender_check || sender_check.value().empty()) {
    // Not enough funds, rollback
    rollback(txn);
    return false;
  }

  // Add amount to receiver
  auto add_result = update<Account>(
      col<"balance">.set(col<"balance"> + amount)
  ) | where(col<"account_id"> == to_account_id)
  )(txn);

  if (!add_result) {
    rollback(txn);
    return false;
  }

  // Commit transaction
  auto commit_result = commit(txn);
  return commit_result.has_value();
}

}  // namespace transaction_transfer_funds
