#include <chrono>

namespace update_order_status {

struct Order {
  sqlgen::PrimaryKey<int> order_id;
  std::string status;
  sqlgen::DateTime order_date;
  double total_amount;
};

int update_order_status() {
  // Connect to the SQLite database
  auto conn_result = sqlgen::sqlite::connect("test_db.sqlite");

  if (!conn_result) {
    return -1; // Return -1 on connection failure
  }

  auto conn = conn_result.value();

  // Define columns for easier usage
  using namespace sqlgen::literals;
  constexpr auto status_col = "status"_c;
  constexpr auto order_date_col = "order_date"_c;

  // Update pending orders older than 7 days to expired
  auto update_expired_result = sqlgen::update<Order>(status_col.set("expired")) |
                               sqlgen::where(status_col == "pending" && 
                                            order_date_col < (sqlgen::now() - std::chrono::days(7)));

  auto result1 = update_expired_result(conn);
  if (!result1) {
    return -1; // Return -1 on update failure
  }

  // Get the number of rows affected by the first update
  int rows_affected = conn->rows_affected();

  // Update shipped orders to delivered (simulated delivery confirmation)
  auto update_delivered_result = sqlgen::update<Order>(status_col.set("delivered")) |
                                 sqlgen::where(status_col == "shipped");

  auto result2 = update_delivered_result(conn);
  if (!result2) {
    return -1; // Return -1 on update failure
  }

  // Add the rows affected by the second update
  rows_affected += conn->rows_affected();

  return rows_affected;
}

} // namespace update_order_status

