      return transpilation::Operation<transpilation::Operator::plus,
                                      transpilation::Col<_name, _alias>,
                                      OtherType>{
          .operand1 = transpilation::Col<_name, _alias>{},
          .operand2 = transpilation::to_transpilation_type(_op2)};
    }
  }
};

