/**
 * Analyze social network data by creating temporary SQL tables for User and Friendship.
 * Returns: std::vector<FriendConnection>.
 */
std::vector<FriendConnection> analyze_social_network_impl(const std::vector<User>& users, const std::vector<Friendship>& friendships) {
  auto db = sqlgen::sqlite::connect("test_db.sqlite")
    | sqlgen::create_table<User>
    | sqlgen::create_table<Friendship>;

  // Insert users
  for (const auto& user : users) {
    db = std::move(db) | sqlgen::insert_into<User>(
      user.user_id.value(), 
      user.username, 
      user.email, 
      user.join_date, 
      user.city
    );
  }

  // Insert friendships (ensure symmetry for undirected graph)
  for (const auto& friendship : friendships) {
    db = std::move(db) | sqlgen::insert_into<Friendship>(
      friendship.user_id1,
      friendship.user_id2,
      friendship.friendship_date
    );
    db = std::move(db) | sqlgen::insert_into<Friendship>(
      friendship.user_id2,
      friendship.user_id1,
      friendship.friendship_date
    );
  }

  // 1. Use SELF-JOIN to find mutual friends
  auto mutual_friends_result = db | sqlgen::select_from<User, "u1"_c>(
    "u1"_c.username,
    "u2"_c.username,
    sqlgen::count()
  )
  | sqlgen::inner_join<User, "u2"_c>("u1"_c.user_id < "u2"_c.user_id)
  | sqlgen::inner_join<Friendship, "f1"_c>("f1"_c.user_id1 == "u1"_c.user_id)
  | sqlgen::inner_join<Friendship, "f2"_c>(
      ("f2"_c.user_id1 == "u2"_c.user_id) && 
      ("f1"_c.user_id2 == "f2"_c.user_id2)
    )
  | sqlgen::group_by("u1"_c.user_id, "u2"_c.user_id)
  | sqlgen::having(sqlgen::count() > 0)
  | sqlgen::to<std::vector<FriendConnection>>;

  std::vector<FriendConnection> connections;
  if (mutual_friends_result) {
    connections = std::move(*mutual_friends_result);
  }

  // 2. Use nested query to find users with more than N friends
  // First, get friend counts per user
  auto friend_counts = db | sqlgen::select_from<User, "u"_c>(
    "u"_c.user_id,
    "u"_c.username,
    sqlgen::count("f"_c.user_id2)
  )
  | sqlgen::left_join<Friendship, "f"_c>("u"_c.user_id == "f"_c.user_id1)
  | sqlgen::group_by("u"_c.user_id, "u"_c.username)
  | sqlgen::to<std::vector<struct {
      int user_id;
      std::string username;
      int friend_count;
  }>>;

  // Calculate average friend count
  int total_friends = 0;
  for (const auto& fc : *friend_counts) {
    total_friends += fc.friend_count;
  }
  double avg_friend_count = static_cast<double>(total_friends) / friend_counts->size();

  // Filter users with more friends than average
  std::vector<std::string> popular_users;
  for (const auto& fc : *friend_counts) {
    if (fc.friend_count > avg_friend_count) {
      popular_users.push_back(fc.username);
    }
