  | sqlgen::inner_join<User, "u3"_c>(
      ("u2"_c.user_id != "u3"_c.user_id) && 
      ("u1"_c.user_id != "u3"_c.user_id)
    )
  | sqlgen::inner_join<Friendship, "f1"_c>(
      ("f1"_c.user_id1 == "u1"_c.user_id) && 
      ("f1"_c.user_id2 == "u2"_c.user_id)
    )
  | sqlgen::inner_join<Friendship, "f2"_c>(
      ("f2"_c.user_id1 == "u2"_c.user_id) && 
      ("f2"_c.user_id2 == "u3"_c.user_id)
    )
  | sqlgen::left_join<Friendship, "f3"_c>(
      ("f3"_c.user_id1 == "u1"_c.user_id) && 
      ("f3"_c.user_id2 == "u3"_c.user_id)
    )
  | sqlgen::where("f3"_c.user_id1.is_null())
  | sqlgen::group_by("u1"_c.user_id, "u3"_c.user_id)
  | sqlgen::having(sqlgen::count() > 0)
  | sqlgen::to<std::vector<FriendConnection>>;

  if (friend_of_friend_result) {
    connections.insert(connections.end(), friend_of_friend_result->begin(), friend_of_friend_result->end());
  }

  // 4. Count friends per user and identify most connected users
  auto user_friend_counts = db | sqlgen::select_from<User, "u"_c>(
    "u"_c.username,
    sqlgen::count("f"_c.user_id2)
  )
  | sqlgen::left_join<Friendship, "f"_c>("u"_c.user_id == "f"_c.user_id1)
  | sqlgen::group_by("u"_c.user_id, "u"_c.username)
  | sqlgen::order_by(sqlgen::desc(sqlgen::count("f"_c.user_id2)))
  | sqlgen::limit(5)
  | sqlgen::to<std::vector<struct {
      std::string username;
      int friend_count;
  }>>;

  // 5. Find users in the same city who are not yet friends
  auto recommendation_result = db | sqlgen::select_from<User, "u1"_c>(
    "u1"_c.username,
    "u2"_c.username
  )
  | sqlgen::inner_join<User, "u2"_c>(
      ("u1"_c.city == "u2"_c.city) &&
      ("u1"_c.user_id < "u2"_c.user_id) &&
      "u1"_c.city.is_not_null() &&
      "u2"_c.city.is_not_null()
  )
  | sqlgen::left_join<Friendship, "f"_c>(
      (("f"_c.user_id1 == "u1"_c.user_id) && ("f"_c.user_id2 == "u2"_c.user_id)) ||
      (("f"_c.user_id1 == "u2"_c.user_id) && ("f"_c.user_id2 == "u1"_c.user_id))
  )
  | sqlgen::where("f"_c.user_id1.is_null())
  | sqlgen::to<std::vector<struct {
      std::string user1_name;
      std::string user2_name;
  }>>;

  if (recommendation_result) {
    for (const auto& rec : *recommendation_result) {
      connections.push_back({rec.user1_name, rec.user2_name, 0});
    }
  }

  return connections;
}

}  // namespace analyze_social_network
