```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace cascade_delete_demo {

struct Parent {
  sqlgen::PrimaryKey<int> parent_id;
  std::string name;
};

struct Child {
  sqlgen::PrimaryKey<int> child_id;
  sqlgen::ForeignKey<int, Parent, "parent_id"> parent_id;
  std::string note;
};

/**
 * Demonstrates cascade delete behavior in SQLite using foreign key constraints.
 * Returns: bool.
 */
bool cascade_delete_demo() {
  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Enable foreign key constraints
  conn = conn.and_then([](const auto& c) {
    return c->execute("PRAGMA foreign_keys = ON").transform([&](const auto&) {
      return c;
    });
  });

  // Create Parent table
  conn = conn.and_then(sqlgen::create_table<Parent>);

  // Create Child table with cascade delete
  using ChildWithCascade = Child;
  conn = conn.and_then(sqlgen::create_table<ChildWithCascade>);

  // Insert a parent record
  Parent parent_record{.parent_id = 1, .name = "Parent1"};
  conn = conn.and_then(sqlgen::insert(parent_record));

  // Insert child records referencing the parent
  Child child1{.child_id = 1, .parent_id = 1, .note = "Child1"};
  Child child2{.child_id = 2, .parent_id = 1, .note = "Child2"};
  conn = conn.and_then(sqlgen::insert(child1));
  conn = conn.and_then(sqlgen::insert(child2));

  // Verify children were inserted
  int child_count_before = 0;
  conn = conn.and_then([&](const auto& c) {
    return c->execute("SELECT COUNT(*) FROM Child WHERE parent_id = 1")
        .transform([&](const auto& result) {
          child_count_before = result.template get<int>(0);
          return c;
        });
  });

  // Delete the parent record
  using namespace sqlgen::literals;
  conn = conn.and_then(
      sqlgen::delete_from<Parent> | sqlgen::where("parent_id"_c == 1));

  // Check if children were automatically deleted
  int child_count_after = 0;
  conn = conn.and_then([&](const auto& c) {
    return c->execute("SELECT COUNT(*) FROM Child WHERE parent_id = 1")
        .transform([&](const auto& result) {
          child_count_after = result.template get<int>(0);
          return c;
        });
  });

  // Return true if cascade delete worked (children were deleted automatically)
  return child_count_before == 2 && child_count_after == 0;
}

}  // namespace cascade_delete_demo
```

