      return false;
    }

    // Create Account table
    auto create_result = conn | sqlgen::create_table<Account>;
    if (!create_result) {
      return false;
    }

    // Insert some initial data for testing
    std::vector<Account> accounts = {
        {.account_id = 1, .balance = 1000.0, .status = "active"},
        {.account_id = 2, .balance = 2000.0, .status = "inactive"},
        {.account_id = 3, .balance = 1500.0, .status = "active"}};

    auto write_result = create_result | sqlgen::write(accounts);
    if (!write_result) {
      return false;
    }

    // Define columns for update operations
    auto balance_col = sqlgen::col<"balance">;
    auto status_col = sqlgen::col<"status">;

    // Update balances and statuses using set(...)
    auto update_result = write_result |
                         sqlgen::update<Account>(balance_col.set(3000.0), 
                                                status_col.set("premium")) |
                         sqlgen::where(sqlgen::col<"account_id"> == 1);

    if (!update_result) {
      return false;
    }

    // Another update operation
    auto update_result2 = update_result |
                          sqlgen::update<Account>(balance_col.set(2500.0)) |
                          sqlgen::where(sqlgen::col<"account_id"> == 2);

    if (!update_result2) {
      return false;
    }

    // Verify changes persisted by querying the data
    const auto select_query = 
        sqlgen::select<sqlgen::fields_t<Account>>()
        .from<sqlgen::table_t<Account>>()
        .where(sqlgen::col<"account_id"> == 1);

    auto verify_result = update_result2 | sqlgen::query(select_query);
    if (!verify_result) {
      return false;
    }

    auto result_vec = verify_result.value();
    if (result_vec.empty()) {
      return false;
    }

    const auto& first_account = result_vec[0];
    if (first_account.balance != 3000.0 || first_account.status != "premium") {
      return false;
    }

    // Verify second update
    const auto select_query2 = 
        sqlgen::select<sqlgen::fields_t<Account>>()
        .from<sqlgen::table_t<Account>>()
        .where(sqlgen::col<"account_id"> == 2);

    auto verify_result2 = update_result2 | sqlgen::query(select_query2);
    if (!verify_result2) {
      return false;
    }

    auto result_vec2 = verify_result2.value();
    if (result_vec2.empty()) {
      return false;
    }

    const auto& second_account = result_vec2[0];
    if (second_account.balance != 2500.0) {
      return false;
    }

    return true;
  } catch (...) {
    return false;
  }
}

}  // namespace update_set_operations
